    for(k=0; k<n+2; ++k) number_list[k]=true;

    //Descartando números compostos
   for(j=1; j<n; ++j){
     for(i=1; i<j; ++i){
       if((i+j+2*i*j)<n) number_list[i+j+2*i*j]=false;
     };
